
CREATE TABLE companies (company_id TEXT PRIMARY KEY, name TEXT NOT NULL, business TEXT NOT NULL);
CREATE TABLE people (company_id TEXT NOT NULL, person_id TEXT NOT NULL, name TEXT NOT NULL, department TEXT NOT NULL, PRIMARY KEY(company_id,person_id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE projects (company_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, owner_id TEXT NOT NULL, budget_twd INTEGER NOT NULL CHECK(budget_twd>0), PRIMARY KEY(company_id,project_id), FOREIGN KEY(company_id,owner_id) REFERENCES people(company_id,person_id));
CREATE TABLE tasks (company_id TEXT NOT NULL, task_id TEXT NOT NULL, project_id TEXT NOT NULL, owner_id TEXT NOT NULL, title TEXT NOT NULL, phase TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('done','doing','review','rejected','todo','blocked')), start_date TEXT NOT NULL, due_date TEXT NOT NULL, completed_date TEXT, estimated_hours INTEGER NOT NULL, actual_hours INTEGER NOT NULL, PRIMARY KEY(company_id,task_id), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,project_id), FOREIGN KEY(company_id,owner_id) REFERENCES people(company_id,person_id), CHECK(start_date<=due_date), CHECK(completed_date IS NULL OR completed_date>=start_date));
CREATE TABLE suppliers (company_id TEXT NOT NULL, supplier_id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, PRIMARY KEY(company_id,supplier_id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE purchase_orders (company_id TEXT NOT NULL, order_id TEXT NOT NULL, project_id TEXT NOT NULL, supplier_id TEXT NOT NULL, item TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_price_twd INTEGER NOT NULL, amount_twd INTEGER NOT NULL, ordered_date TEXT NOT NULL, promised_date TEXT NOT NULL, received_date TEXT, status TEXT NOT NULL CHECK(status IN ('received','pending','cancelled')), PRIMARY KEY(company_id,order_id), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,project_id), FOREIGN KEY(company_id,supplier_id) REFERENCES suppliers(company_id,supplier_id), CHECK(amount_twd=quantity*unit_price_twd));
CREATE TABLE expenses (company_id TEXT NOT NULL, expense_id TEXT NOT NULL, project_id TEXT NOT NULL, category TEXT NOT NULL, booked_date TEXT NOT NULL, amount_twd INTEGER NOT NULL CHECK(amount_twd>=0), PRIMARY KEY(company_id,expense_id), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,project_id));
CREATE TABLE quality_checks (company_id TEXT NOT NULL, check_id TEXT NOT NULL, project_id TEXT NOT NULL, checked_date TEXT NOT NULL, sample_count INTEGER NOT NULL, defect_count INTEGER NOT NULL, criterion TEXT NOT NULL, PRIMARY KEY(company_id,check_id), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,project_id), CHECK(defect_count>=0 AND defect_count<=sample_count));
CREATE TABLE risks (company_id TEXT NOT NULL, risk_id TEXT NOT NULL, project_id TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL, cause TEXT NOT NULL, impact TEXT NOT NULL, action TEXT NOT NULL, owner_id TEXT NOT NULL, next_review_date TEXT NOT NULL, PRIMARY KEY(company_id,risk_id), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,project_id), FOREIGN KEY(company_id,owner_id) REFERENCES people(company_id,person_id));
CREATE TABLE notes (company_id TEXT NOT NULL, note_id TEXT NOT NULL, task_id TEXT NOT NULL, created_date TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(company_id,note_id), FOREIGN KEY(company_id,task_id) REFERENCES tasks(company_id,task_id));
